// ── Write ───────────────────────────────────────────────────────────────────

const here = dirname(fileURLToPath(import.meta.url));
const outPath = resolve(here, "../../../content-packs/sleep-history/topic/drinks-and-spices-histories/content/topic-pack.json");
mkdirSync(dirname(outPath), { recursive: true });
writeFileSync(outPath, JSON.stringify(document, null, 2) + "\n", "utf8");

// ── Audit ───────────────────────────────────────────────────────────────────

const problems = [];
const note = message => problems.push(message);

if (coverage_profiles.length !== 50) note(`expected 50 coverage profiles, found ${coverage_profiles.length}`);
coverage_profiles.forEach((profile, index) => {
  if (profile.subject !== SUBJECTS[index]) note(`profile ${index} subject "${profile.subject}" does not match subject list entry "${SUBJECTS[index]}"`);
  if (profile.tuples.length !== 20) note(`subject "${profile.subject}" has ${profile.tuples.length} tuples, expected 20`);
  const objects = new Set(), mechanisms = new Set();
  for (const tuple of profile.tuples) {
    if (objects.has(tuple.episode_object)) note(`subject "${profile.subject}" repeats episode_object: ${tuple.episode_object}`);
    if (mechanisms.has(tuple.mechanism)) note(`subject "${profile.subject}" repeats mechanism: ${tuple.mechanism}`);
    objects.add(tuple.episode_object);
    mechanisms.add(tuple.mechanism);
  }
});

const pairSeen = new Map(), fullSeen = new Map();
for (const profile of coverage_profiles) {
  for (const tuple of profile.tuples) {
    const pair = `${tuple.episode_object}|${tuple.mechanism}`;
    const full = `${tuple.episode_object}|${tuple.time_place_scope}|${tuple.mechanism}|${tuple.evidence_lens}`;
    if (pairSeen.has(pair)) note(`duplicate episode_object|mechanism pair (${profile.subject} and ${pairSeen.get(pair)}): ${pair}`);
    else pairSeen.set(pair, profile.subject);
    if (fullSeen.has(full)) note(`duplicate full tuple (${profile.subject} and ${fullSeen.get(full)})`);
    else fullSeen.set(full, profile.subject);
  }
}

const LENGTH_BOUNDS = {
  episode_object: [40, 140],
  time_place_scope: [40, 140],
  mechanism: [40, 160],
  evidence_lens: [40, 160],
};
for (const profile of coverage_profiles) {
  for (const tuple of profile.tuples) {
    for (const [field, [min, max]] of Object.entries(LENGTH_BOUNDS)) {
      const length = tuple[field].length;
      if (length < min || length > max) note(`${profile.subject} ${field} length ${length} outside ${min}-${max}: ${tuple[field]}`);
    }
  }
}

const FORBIDDEN_WORDS = /\b(YouTube|TikTok|Instagram|Facebook|Microsoft|Photoshop|Illustrator|Vimeo|Twitch)\b/i;
const UNSAFE_REFERENCE = /(?:\b[a-z][a-z0-9+.-]*:\S+|(?:^|[\s(])\/\/\S+|\bwww\.\S+|\b(?:[a-z0-9-]+\.)+[a-z]{2,}(?:\/\S*)?)/i;
const ROUTING_DIRECTIVE = /\b(?:provider_id|model_id|engine_id)\b|\bprovider\s*(?::|=)\s*[^\s]+|\bmodel\s*(?::|=)\s*[^\s]+/i;
const SENSITIVE_ASSIGNMENT = /(?:^|[\s,{;])(?:["']?(?:api(?:[_ -]?key)|secret|(?:access[_ -]?token)|token|bearer|account(?:[_ -]?id)|customer(?:[_ -]?id))["']?)\s*(?:[:=]\s*)/i;

// Reverse-DNS identifier fields are validated by the schema as qualified ids,
// not as free prose, so the URI-shape check does not apply to them. The
// prompt_context is allowed a longer budget (1500) than an ordinary string.
const ID_PATHS = new Set(["document.id", "document.compatible_formula_ids[0]"]);

const walkStrings = (value, path) => {
  if (typeof value === "string") {
    const maxLength = path === "document.prompt_context" ? 1500 : 1000;
    if (value.length < 1 || value.length > maxLength) note(`${path}: string length ${value.length} outside 1-${maxLength}`);
    if (FORBIDDEN_WORDS.test(value)) note(`${path}: forbidden platform or product name: ${value}`);
    if (!ID_PATHS.has(path) && UNSAFE_REFERENCE.test(value)) note(`${path}: URI-like reference: ${value}`);
    if (ROUTING_DIRECTIVE.test(value)) note(`${path}: routing directive: ${value}`);
    if (SENSITIVE_ASSIGNMENT.test(value)) note(`${path}: credential-shaped assignment: ${value}`);
  } else if (Array.isArray(value)) {
    value.forEach((entry, index) => walkStrings(entry, `${path}[${index}]`));
  } else if (value && typeof value === "object") {
    for (const [key, entry] of Object.entries(value)) walkStrings(entry, `${path}.${key}`);
  }
};
walkStrings(document, "document");

const bytes = statSync(outPath).size;
console.log(`subjects:            ${document.subjects.length}`);
console.log(`coverage profiles:   ${coverage_profiles.length}`);
console.log(`tuples:              ${allTuples.length}`);
console.log(`episode_objects:     ${document.episode_objects.length}`);
console.log(`time_place_scopes:   ${document.time_place_scopes.length}`);
console.log(`mechanisms:          ${document.mechanisms.length}`);
console.log(`evidence_lenses:     ${document.evidence_lenses.length}`);
console.log(`prompt_context:      ${document.prompt_context.length} chars`);
console.log(`written:             ${outPath} (${bytes} bytes)`);
console.log(problems.length === 0 ? "AUDIT OK" : `AUDIT FAILED (${problems.length} problems)`);
for (const problem of problems.slice(0, 400)) console.log(`  - ${problem}`);
